Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_append_n_resize_failure(void) {
    // Setup: create a buffer with small content so that appending will require resize
    buffer_t *buf = helper_create_buffer_with_content("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // Prepare string to append
    const char *to_append = "defgh";
    size_t append_len = 5;

    // The buffer's initial size is just enough for "abc" (len = 3), so appending 5 more will require resize
    // We want buffer_resize to fail. 
    // helper_create_buffer_with_content("abc") calls buffer_new_with_copy, which calls buffer_new_with_size (2 allocations)
    // So, to fail the realloc in buffer_resize, we need to fail the 3rd allocation
    malloc_fail_after(2);

    int ret = buffer_append_n(buf, to_append, append_len);

    // Should return -1 on allocation failure
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer content should remain unchanged
    helper_assert_buffer_content(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_failure);
    return UNITY_END();
}


